#define WRITE 2
#define STARTING_SEED 1070

typedef struct { double energy,total_xs,elastic_xs,absorbtion_xs,fission_xs,nu_fission_xs; } NuclideGridPoint;
typedef struct { int nthreads; long n_isotopes,n_gridpoints; int lookups; char *HM; int grid_type,hash_bins,particles,simulation_method,binary_mode,kernel_id; } Inputs;
typedef struct {
    int *num_nucs; double *concs; int *mats; double *unionized_energy_array; int *index_grid; NuclideGridPoint *nuclide_grid;
    int length_num_nucs,length_concs,length_mats,length_unionized_energy_array; long length_index_grid; int length_nuclide_grid,max_num_nucs;
    unsigned long *verification; int length_verification; double *p_energy_samples; int length_p_energy_samples; int *mat_samples; int length_mat_samples;
} SimulationData;

static sycl::queue *gq=nullptr;
static sycl::queue &get_queue(){ if(!gq){ auto ah=[](sycl::exception_list el){ for(auto &e:el){ try{std::rethrow_exception(e);}catch(const sycl::exception &ex){fprintf(stderr,"SYCL asynchronous exception: %s\n",ex.what()); exit(1);}}}; try{gq=new sycl::queue(sycl::gpu_selector_v,ah);}catch(...){gq=new sycl::queue(sycl::default_selector_v,ah);} } return *gq; }
template<class T> static T *device_alloc_copy(const T *src,size_t n){ if(!n) return nullptr; auto &q=get_queue(); T *d=sycl::malloc_device<T>(n,q); if(!d){fprintf(stderr,"SYCL device allocation failed\n"); exit(1);} if(src) q.memcpy(d,src,n*sizeof(T)).wait(); return d; }
template<class T> static T *device_alloc(size_t n){ if(!n) return nullptr; auto &q=get_queue(); T *d=sycl::malloc_device<T>(n,q); if(!d){fprintf(stderr,"SYCL device allocation failed\n"); exit(1);} return d; }

