inline long grid_search_nuclide(long n,double quarry,NuclideGridPoint *A,long low,long high){ long l=low,u=high,p,len=u-l; while(len>1){p=l+len/2; if(A[p].energy>quarry) u=p; else l=p; len=u-l;} return l; }
inline long grid_search(long n,double quarry,double *A){ long l=0,u=n-1,p,len=u-l; while(len>1){p=l+len/2; if(A[p]>quarry) u=p; else l=p; len=u-l;} return l; }
inline double LCG_random_double(uint64_t *seed){ const uint64_t m=9223372036854775808ULL,a=2806196910506780709ULL,c=1ULL; *seed=(a*(*seed)+c)%m; return (double)(*seed)/(double)m; }
inline uint64_t fast_forward_LCG(uint64_t seed,uint64_t n){ const uint64_t m=9223372036854775808ULL; uint64_t a=2806196910506780709ULL,c=1ULL,an=1,cn=0; n%=m; while(n){ if(n&1){an*=a; cn=cn*a+c;} c*=(a+1); a*=a; n>>=1;} return (an*seed+cn)%m; }
inline int pick_mat(uint64_t *seed){ double dist[12]={0.140,0.052,0.275,0.134,0.154,0.064,0.066,0.055,0.008,0.015,0.025,0.013}; double roll=LCG_random_double(seed); for(int i=0;i<12;i++){ double r=0; for(int j=i;j>0;j--) r+=dist[j]; if(roll<r) return i;} return 0; }

inline void calculate_micro_xs(double p_energy,int nuc,long n_isotopes,long n_gridpoints,double *egrid,int *index_data,NuclideGridPoint *nuclide_grids,long idx,double *xs_vector,int grid_type,int hash_bins){
    double f; NuclideGridPoint *low,*high;
    if(grid_type==NUCLIDE){ idx=grid_search_nuclide(n_gridpoints,p_energy,&nuclide_grids[nuc*n_gridpoints],0,n_gridpoints-1); low=&nuclide_grids[nuc*n_gridpoints+idx-(idx==n_gridpoints-1)]; }
    else if(grid_type==UNIONIZED){ int id=index_data[idx*n_isotopes+nuc]; low=&nuclide_grids[nuc*n_gridpoints+id-(id==n_gridpoints-1)]; }
    else{ int u_low=index_data[idx*n_isotopes+nuc],u_high=(idx==hash_bins-1)?n_gridpoints-1:index_data[(idx+1)*n_isotopes+nuc]+1,lower; double e_low=nuclide_grids[nuc*n_gridpoints+u_low].energy,e_high=nuclide_grids[nuc*n_gridpoints+u_high].energy; if(p_energy<=e_low) lower=0; else if(p_energy>=e_high) lower=n_gridpoints-1; else lower=grid_search_nuclide(n_gridpoints,p_energy,&nuclide_grids[nuc*n_gridpoints],u_low,u_high); low=&nuclide_grids[nuc*n_gridpoints+lower-(lower==n_gridpoints-1)]; }
    high=low+1; f=(high->energy-p_energy)/(high->energy-low->energy);
    xs_vector[0]=high->total_xs-f*(high->total_xs-low->total_xs); xs_vector[1]=high->elastic_xs-f*(high->elastic_xs-low->elastic_xs);
    xs_vector[2]=high->absorbtion_xs-f*(high->absorbtion_xs-low->absorbtion_xs); xs_vector[3]=high->fission_xs-f*(high->fission_xs-low->fission_xs);
    xs_vector[4]=high->nu_fission_xs-f*(high->nu_fission_xs-low->nu_fission_xs);
}
inline void calculate_macro_xs(double p_energy,int mat,long n_isotopes,long n_gridpoints,int *num_nucs,double *concs,double *egrid,int *index_data,NuclideGridPoint *nuclide_grids,int *mats,double *macro_xs_vector,int grid_type,int hash_bins,int max_num_nucs){
    long idx=-1; for(int k=0;k<5;k++) macro_xs_vector[k]=0;
    if(grid_type==UNIONIZED) idx=grid_search(n_isotopes*n_gridpoints,p_energy,egrid); else if(grid_type==HASH){ double du=1.0/hash_bins; idx=p_energy/du; if(idx<0) idx=0; if(idx>=hash_bins) idx=hash_bins-1; }
    for(int j=0;j<num_nucs[mat];j++){ double xs[5]; int p_nuc=mats[mat*max_num_nucs+j]; double conc=concs[mat*max_num_nucs+j]; calculate_micro_xs(p_energy,p_nuc,n_isotopes,n_gridpoints,egrid,index_data,nuclide_grids,idx,xs,grid_type,hash_bins); for(int k=0;k<5;k++) macro_xs_vector[k]+=xs[k]*conc; }
}

static void launch_sampling_kernel(Inputs in,SimulationData GSD,int nthreads){ auto &q=get_queue(); size_t global=((size_t)in.lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=in.lookups) return; uint64_t seed=fast_forward_LCG(STARTING_SEED,2ULL*i); GSD.p_energy_samples[i]=LCG_random_double(&seed); GSD.mat_samples[i]=pick_mat(&seed); }); }).wait(); }
static void launch_baseline_kernel(Inputs in,SimulationData GSD,int nthreads){ auto &q=get_queue(); size_t global=((size_t)in.lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=in.lookups) return; uint64_t seed=fast_forward_LCG(STARTING_SEED,2ULL*i); double e=LCG_random_double(&seed); int mat=pick_mat(&seed); double v[5]={0}; calculate_macro_xs(e,mat,in.n_isotopes,in.n_gridpoints,GSD.num_nucs,GSD.concs,GSD.unionized_energy_array,GSD.index_grid,GSD.nuclide_grid,GSD.mats,v,in.grid_type,in.hash_bins,GSD.max_num_nucs); double mx=-1; int mi=0; for(int j=0;j<5;j++) if(v[j]>mx){mx=v[j];mi=j;} GSD.verification[i]=mi+1; }); }).wait(); }
static void launch_lookup1_kernel(Inputs in,SimulationData GSD,int nthreads){ auto &q=get_queue(); size_t global=((size_t)in.lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=in.lookups) return; double v[5]={0}; calculate_macro_xs(GSD.p_energy_samples[i],GSD.mat_samples[i],in.n_isotopes,in.n_gridpoints,GSD.num_nucs,GSD.concs,GSD.unionized_energy_array,GSD.index_grid,GSD.nuclide_grid,GSD.mats,v,in.grid_type,in.hash_bins,GSD.max_num_nucs); double mx=-1; int mi=0; for(int j=0;j<5;j++) if(v[j]>mx){mx=v[j];mi=j;} GSD.verification[i]=mi+1; }); }).wait(); }
static void launch_lookup2_kernel(Inputs in,SimulationData GSD,int m,int nthreads){ auto &q=get_queue(); size_t global=((size_t)in.lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=in.lookups) return; int mat=GSD.mat_samples[i]; if(mat!=m) return; double v[5]={0}; calculate_macro_xs(GSD.p_energy_samples[i],mat,in.n_isotopes,in.n_gridpoints,GSD.num_nucs,GSD.concs,GSD.unionized_energy_array,GSD.index_grid,GSD.nuclide_grid,GSD.mats,v,in.grid_type,in.hash_bins,GSD.max_num_nucs); double mx=-1; int mi=0; for(int j=0;j<5;j++) if(v[j]>mx){mx=v[j];mi=j;} GSD.verification[i]=mi+1; }); }); }
static void launch_lookup3_kernel(Inputs in,SimulationData GSD,int is_fuel,int nthreads){ auto &q=get_queue(); size_t global=((size_t)in.lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=in.lookups) return; int mat=GSD.mat_samples[i]; if(((is_fuel==1)&&(mat==0))||((is_fuel==0)&&(mat!=0))){ double v[5]={0}; calculate_macro_xs(GSD.p_energy_samples[i],mat,in.n_isotopes,in.n_gridpoints,GSD.num_nucs,GSD.concs,GSD.unionized_energy_array,GSD.index_grid,GSD.nuclide_grid,GSD.mats,v,in.grid_type,in.hash_bins,GSD.max_num_nucs); double mx=-1; int mi=0; for(int j=0;j<5;j++) if(v[j]>mx){mx=v[j];mi=j;} GSD.verification[i]=mi+1; } }); }); }
static void launch_lookup4_kernel(Inputs in,SimulationData GSD,int m,int n_lookups,int offset,int nthreads){ if(n_lookups<=0) return; auto &q=get_queue(); size_t global=((size_t)n_lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=n_lookups) return; i+=offset; int mat=GSD.mat_samples[i]; if(mat!=m) return; double v[5]={0}; calculate_macro_xs(GSD.p_energy_samples[i],mat,in.n_isotopes,in.n_gridpoints,GSD.num_nucs,GSD.concs,GSD.unionized_energy_array,GSD.index_grid,GSD.nuclide_grid,GSD.mats,v,in.grid_type,in.hash_bins,GSD.max_num_nucs); double mx=-1; int mi=0; for(int j=0;j<5;j++) if(v[j]>mx){mx=v[j];mi=j;} GSD.verification[i]=mi+1; }); }); }
static void launch_lookup5_kernel(Inputs in,SimulationData GSD,int n_lookups,int offset,int nthreads){ if(n_lookups<=0) return; auto &q=get_queue(); size_t global=((size_t)n_lookups+nthreads-1)/nthreads*nthreads; q.submit([&](sycl::handler &h){ h.parallel_for(sycl::nd_range<1>(global,nthreads),[=](sycl::nd_item<1> it){ int i=it.get_global_linear_id(); if(i>=n_lookups) return; i+=offset; double v[5]={0}; calculate_macro_xs(GSD.p_energy_samples[i],GSD.mat_samples[i],in.n_isotopes,in.n_gridpoints,GSD.num_nucs,GSD.concs,GSD.unionized_energy_array,GSD.index_grid,GSD.nuclide_grid,GSD.mats,v,in.grid_type,in.hash_bins,GSD.max_num_nucs); double mx=-1; int mi=0; for(int j=0;j<5;j++) if(v[j]>mx){mx=v[j];mi=j;} GSD.verification[i]=mi+1; }); }); }

static unsigned long long reduce_verification(SimulationData GSD,int n){
    sycl::queue &q=get_queue();
    unsigned long long *res=sycl::malloc_shared<unsigned long long>(1,q);
    *res=0;
    q.submit([&](sycl::handler &h){
        auto red=sycl::reduction(res, (unsigned long long)0, sycl::plus<unsigned long long>());
        h.parallel_for(sycl::range<1>(n), red, [=](sycl::id<1> idx, auto &sum){ sum += (unsigned long long)GSD.verification[idx]; });
    }).wait();
    unsigned long long out=*res; sycl::free(res,q); return out;
}
static void allocate_samples(Inputs in,SimulationData &GSD,int mype){ if(mype==0) printf("Allocating additional device data required by kernel...\n"); size_t sz=0; GSD.p_energy_samples=device_alloc<double>(in.lookups); GSD.length_p_energy_samples=in.lookups; sz+=in.lookups*sizeof(double); GSD.mat_samples=device_alloc<int>(in.lookups); GSD.length_mat_samples=in.lookups; sz+=in.lookups*sizeof(int); if(mype==0) printf("Allocated an additional %.0lf MB of data on GPU.\n",sz/1024.0/1024.0); }
static std::vector<int> copy_samples_to_host_count(SimulationData GSD,int n,std::vector<int> &mat,std::vector<double> &energy){ auto &q=get_queue(); mat.resize(n); energy.resize(n); q.memcpy(mat.data(),GSD.mat_samples,n*sizeof(int)).wait(); q.memcpy(energy.data(),GSD.p_energy_samples,n*sizeof(double)).wait(); std::vector<int> counts(12,0); for(int v:mat) if(v>=0&&v<12) counts[v]++; return counts; }
static void copy_samples_to_device(const std::vector<int> &mat,const std::vector<double> &energy,SimulationData GSD){ auto &q=get_queue(); int n=mat.size(); q.memcpy(GSD.mat_samples,mat.data(),n*sizeof(int)); q.memcpy(GSD.p_energy_samples,energy.data(),n*sizeof(double)).wait(); }

int main(int argc,char *argv[]){ int version=20,mype=0,nprocs=1; unsigned long long verification=0; Inputs in=read_CLI(argc,argv); if(mype==0) print_inputs(in,nprocs,version); SimulationData SD=(in.binary_mode==READ)?binary_read(in):grid_init_do_not_profile(in,mype); if(in.binary_mode==WRITE&&mype==0) binary_write(in,SD); SimulationData GSD=move_simulation_data_to_device(in,mype,SD); if(mype==0){printf("\n"); border_print(); center_print("SIMULATION",79); border_print();} double st=get_time(); if(in.simulation_method==EVENT_BASED){ if(in.kernel_id==0) verification=run_event_based_simulation_baseline(in,GSD,mype); else if(in.kernel_id==1) verification=run_event_based_simulation_optimization_1(in,GSD,mype); else if(in.kernel_id==2) verification=run_event_based_simulation_optimization_2(in,GSD,mype); else if(in.kernel_id==3) verification=run_event_based_simulation_optimization_3(in,GSD,mype); else if(in.kernel_id==4) verification=run_event_based_simulation_optimization_4(in,GSD,mype); else if(in.kernel_id==5) verification=run_event_based_simulation_optimization_5(in,GSD,mype); else if(in.kernel_id==6) verification=run_event_based_simulation_optimization_6(in,GSD,mype); else{printf("Error: No kernel ID %d found!\n",in.kernel_id); exit(1);} } else { printf("History-based simulation not implemented in SYCL code. Instead,\nuse the event-based method with \"-m event\" argument.\n"); exit(1);} if(mype==0) printf("\nSimulation complete.\n"); double en=get_time(); release_device_memory(GSD); verification%=999983; return print_results(in,mype,en-st,nprocs,verification); }

void logo(int version){ border_print(); center_print("XSBench",79); char v[100]; sprintf(v,"Version: %d",version); center_print(v,79); border_print(); }
void center_print(const char *s,int width){ int l=strlen(s); for(int i=0;i<=(width-l)/2;i++) fputs(" ",stdout); fputs(s,stdout); fputs("\n",stdout); }
void border_print(void){ printf("===============================================================================\n"); }
void fancy_int(long a){ if(a<1000) printf("%ld\n",a); else if(a<1000000) printf("%ld,%03ld\n",a/1000,a%1000); else if(a<1000000000) printf("%ld,%03ld,%03ld\n",a/1000000,(a%1000000)/1000,a%1000); else printf("%ld,%03ld,%03ld,%03ld\n",a/1000000000,(a%1000000000)/1000000,(a%1000000)/1000,a%1000); }
int print_results(Inputs in,int mype,double runtime,int nprocs,unsigned long long vhash){ int lookups=(in.simulation_method==HISTORY_BASED)?in.lookups*in.particles:in.lookups, lps=(int)((double)lookups/runtime),invalid=1; if(mype==0){ border_print(); center_print("RESULTS",79); border_print(); printf("NOTE: Timings are estimated -- use profiler tooling for formal analysis\nRuntime:     %.3lf seconds\nLookups:     ",runtime); fancy_int(lookups); printf("Lookups/s:   "); fancy_int(lps);} unsigned long long small=0,large=0; if(in.simulation_method==EVENT_BASED){small=945990; large=952131;} else {small=941535; large=954318;} if(strcmp(in.HM,"large")==0){ if(vhash==large) invalid=0; } else if(strcmp(in.HM,"small")==0){ if(vhash==small) invalid=0; } if(mype==0){ if(invalid) printf("Verification checksum: %llu (WARNING - INAVALID CHECKSUM!)\n",vhash); else printf("Verification checksum: %llu (Valid)\n",vhash); border_print(); } return invalid; }
void print_inputs(Inputs in,int nprocs,int version){ int mem=estimate_mem_usage(in); logo(version); center_print("INPUT SUMMARY",79); border_print(); printf("Programming Model:            SYCL\n"); auto &q=get_queue(); printf("SYCL Device:                  %s\n",q.get_device().get_info<sycl::info::device::name>().c_str()); printf("Simulation Method:            %s\n",in.simulation_method==EVENT_BASED?"Event Based":"History Based"); printf("Grid Type:                    %s\n",in.grid_type==NUCLIDE?"Nuclide Grid":(in.grid_type==UNIONIZED?"Unionized Grid":"Hash")); printf("Materials:                    %d\nH-M Benchmark Size:           %s\nTotal Nuclides:               %ld\nGridpoints (per Nuclide):     ",12,in.HM,in.n_isotopes); fancy_int(in.n_gridpoints); if(in.grid_type==HASH){printf("Hash Bins:                    "); fancy_int(in.hash_bins);} if(in.grid_type==UNIONIZED){printf("Unionized Energy Gridpoints:  "); fancy_int(in.n_isotopes*in.n_gridpoints);} if(in.simulation_method==HISTORY_BASED){printf("Particle Histories:           "); fancy_int(in.particles); printf("XS Lookups per Particle:      "); fancy_int(in.lookups);} printf("Total XS Lookups:             "); fancy_int(in.lookups); printf("Est. Memory Usage (MB):       "); fancy_int(mem); printf("Binary File Mode:             %s\n",in.binary_mode==NONE?"Off":(in.binary_mode==READ?"Read":"Write")); border_print(); center_print("INITIALIZATION - DO NOT PROFILE",79); border_print(); }
void print_CLI_error(void){ printf("Usage: ./XSBench <options>\n"); exit(4); }

Inputs read_CLI(int argc,char *argv[]){ Inputs input; input.simulation_method=HISTORY_BASED; input.nthreads=1; input.n_isotopes=355; input.n_gridpoints=11303; input.particles=500000; input.lookups=34; input.grid_type=UNIONIZED; input.hash_bins=10000; input.binary_mode=NONE; input.kernel_id=0; input.HM=(char*)malloc(6); strcpy(input.HM,"large"); int user_g=0,dl=1,dp=1; for(int i=1;i<argc;i++){ char *arg=argv[i]; if(strcmp(arg,"-g")==0){ if(++i<argc){user_g=1; input.n_gridpoints=atol(argv[i]);} else print_CLI_error(); } else if(strcmp(arg,"-m")==0){ char *s; if(++i<argc) s=argv[i]; else print_CLI_error(); if(strcmp(s,"history")==0) input.simulation_method=HISTORY_BASED; else if(strcmp(s,"event")==0){ input.simulation_method=EVENT_BASED; if(dl&&dp){input.lookups*=input.particles; input.particles=0;} } else print_CLI_error(); } else if(strcmp(arg,"-l")==0){ if(++i<argc){input.lookups=atoi(argv[i]); dl=0;} else print_CLI_error(); } else if(strcmp(arg,"-h")==0){ if(++i<argc) input.hash_bins=atoi(argv[i]); else print_CLI_error(); } else if(strcmp(arg,"-p")==0){ if(++i<argc){input.particles=atoi(argv[i]); dp=0;} else print_CLI_error(); } else if(strcmp(arg,"-s")==0){ if(++i<argc) input.HM=argv[i]; else print_CLI_error(); } else if(strcmp(arg,"-G")==0){ char *g; if(++i<argc) g=argv[i]; else print_CLI_error(); if(strcmp(g,"unionized")==0) input.grid_type=UNIONIZED; else if(strcmp(g,"nuclide")==0) input.grid_type=NUCLIDE; else if(strcmp(g,"hash")==0) input.grid_type=HASH; else print_CLI_error(); } else if(strcmp(arg,"-b")==0){ char *b; if(++i<argc) b=argv[i]; else print_CLI_error(); if(strcmp(b,"read")==0) input.binary_mode=READ; else if(strcmp(b,"write")==0) input.binary_mode=WRITE; else print_CLI_error(); } else if(strcmp(arg,"-k")==0){ if(++i<argc) input.kernel_id=atoi(argv[i]); else print_CLI_error(); } else print_CLI_error(); } if(input.nthreads<1||input.n_isotopes<1||input.n_gridpoints<1||input.lookups<1||input.hash_bins<1) print_CLI_error(); if(strcasecmp(input.HM,"small")&&strcasecmp(input.HM,"large")&&strcasecmp(input.HM,"XL")&&strcasecmp(input.HM,"XXL")) print_CLI_error(); if(!strcasecmp(input.HM,"small")) input.n_isotopes=68; else if(!strcasecmp(input.HM,"XL")&&!user_g) input.n_gridpoints=238847; else if(!strcasecmp(input.HM,"XXL")&&!user_g) input.n_gridpoints=(long)(238847*2.1); return input; }

void binary_write(Inputs in,SimulationData SD){ const char *f="XS_data.dat"; printf("Writing all data structures to binary file %s...\n",f); FILE *fp=fopen(f,"wb"); assert(fp); fwrite(&SD,sizeof(SD),1,fp); fwrite(SD.num_nucs,sizeof(int),SD.length_num_nucs,fp); fwrite(SD.concs,sizeof(double),SD.length_concs,fp); fwrite(SD.mats,sizeof(int),SD.length_mats,fp); fwrite(SD.nuclide_grid,sizeof(NuclideGridPoint),SD.length_nuclide_grid,fp); fwrite(SD.index_grid,sizeof(int),SD.length_index_grid,fp); fwrite(SD.unionized_energy_array,sizeof(double),SD.length_unionized_energy_array,fp); fclose(fp); }
SimulationData binary_read(Inputs in){ SimulationData SD; const char *f="XS_data.dat"; printf("Reading all data structures from binary file %s...\n",f); FILE *fp=fopen(f,"rb"); assert(fp); fread(&SD,sizeof(SD),1,fp); SD.num_nucs=(int*)malloc(SD.length_num_nucs*sizeof(int)); SD.concs=(double*)malloc(SD.length_concs*sizeof(double)); SD.mats=(int*)malloc(SD.length_mats*sizeof(int)); SD.nuclide_grid=(NuclideGridPoint*)malloc(SD.length_nuclide_grid*sizeof(NuclideGridPoint)); SD.index_grid=SD.length_index_grid?(int*)malloc(SD.length_index_grid*sizeof(int)):nullptr; SD.unionized_energy_array=SD.length_unionized_energy_array?(double*)malloc(SD.length_unionized_energy_array*sizeof(double)):nullptr; fread(SD.num_nucs,sizeof(int),SD.length_num_nucs,fp); fread(SD.concs,sizeof(double),SD.length_concs,fp); fread(SD.mats,sizeof(int),SD.length_mats,fp); fread(SD.nuclide_grid,sizeof(NuclideGridPoint),SD.length_nuclide_grid,fp); fread(SD.index_grid,sizeof(int),SD.length_index_grid,fp); fread(SD.unionized_energy_array,sizeof(double),SD.length_unionized_energy_array,fp); fclose(fp); return SD; }
SimulationData move_simulation_data_to_device(Inputs in,int mype,SimulationData SD){ if(mype==0) printf("Allocating and moving simulation data to GPU memory space...\n"); size_t sz=0; SimulationData GSD=SD; GSD.num_nucs=device_alloc_copy(SD.num_nucs,GSD.length_num_nucs); sz+=GSD.length_num_nucs*sizeof(int); GSD.concs=device_alloc_copy(SD.concs,GSD.length_concs); sz+=GSD.length_concs*sizeof(double); GSD.mats=device_alloc_copy(SD.mats,GSD.length_mats); sz+=GSD.length_mats*sizeof(int); GSD.unionized_energy_array=device_alloc_copy(SD.unionized_energy_array,GSD.length_unionized_energy_array); sz+=GSD.length_unionized_energy_array*sizeof(double); GSD.index_grid=device_alloc_copy(SD.index_grid,GSD.length_index_grid); sz+=GSD.length_index_grid*sizeof(int); GSD.nuclide_grid=device_alloc_copy(SD.nuclide_grid,GSD.length_nuclide_grid); sz+=GSD.length_nuclide_grid*sizeof(NuclideGridPoint); GSD.verification=device_alloc<unsigned long>(in.lookups); sz+=in.lookups*sizeof(unsigned long); GSD.length_verification=in.lookups; GSD.p_energy_samples=nullptr; GSD.mat_samples=nullptr; GSD.length_p_energy_samples=0; GSD.length_mat_samples=0; get_queue().wait_and_throw(); if(mype==0) printf("GPU Intialization complete. Allocated %.0lf MB of data on GPU.\n",sz/1024.0/1024.0); return GSD; }
void release_device_memory(SimulationData GSD){ auto &q=get_queue(); if(GSD.num_nucs) sycl::free(GSD.num_nucs,q); if(GSD.concs) sycl::free(GSD.concs,q); if(GSD.mats) sycl::free(GSD.mats,q); if(GSD.unionized_energy_array) sycl::free(GSD.unionized_energy_array,q); if(GSD.index_grid) sycl::free(GSD.index_grid,q); if(GSD.nuclide_grid) sycl::free(GSD.nuclide_grid,q); if(GSD.verification) sycl::free(GSD.verification,q); if(GSD.p_energy_samples) sycl::free(GSD.p_energy_samples,q); if(GSD.mat_samples) sycl::free(GSD.mat_samples,q); }

SimulationData grid_init_do_not_profile(Inputs in,int mype){ SimulationData SD; memset(&SD,0,sizeof(SD)); size_t nb=0; uint64_t seed=42; if(mype==0) printf("Intializing nuclide grids...\n"); SD.length_nuclide_grid=in.n_isotopes*in.n_gridpoints; SD.nuclide_grid=(NuclideGridPoint*)malloc(SD.length_nuclide_grid*sizeof(NuclideGridPoint)); assert(SD.nuclide_grid); nb+=SD.length_nuclide_grid*sizeof(NuclideGridPoint); for(int i=0;i<SD.length_nuclide_grid;i++){ SD.nuclide_grid[i].energy=LCG_random_double(&seed); SD.nuclide_grid[i].total_xs=LCG_random_double(&seed); SD.nuclide_grid[i].elastic_xs=LCG_random_double(&seed); SD.nuclide_grid[i].absorbtion_xs=LCG_random_double(&seed); SD.nuclide_grid[i].fission_xs=LCG_random_double(&seed); SD.nuclide_grid[i].nu_fission_xs=LCG_random_double(&seed); } for(int i=0;i<in.n_isotopes;i++) qsort(&SD.nuclide_grid[i*in.n_gridpoints],in.n_gridpoints,sizeof(NuclideGridPoint),NGP_compare);
    if(in.grid_type==NUCLIDE){ SD.length_unionized_energy_array=0; SD.length_index_grid=0; SD.unionized_energy_array=nullptr; SD.index_grid=nullptr; }
    if(in.grid_type==UNIONIZED){ if(mype==0) printf("Intializing unionized grid...\n"); SD.length_unionized_energy_array=in.n_isotopes*in.n_gridpoints; SD.unionized_energy_array=(double*)malloc(SD.length_unionized_energy_array*sizeof(double)); assert(SD.unionized_energy_array); nb+=SD.length_unionized_energy_array*sizeof(double); for(int i=0;i<SD.length_unionized_energy_array;i++) SD.unionized_energy_array[i]=SD.nuclide_grid[i].energy; qsort(SD.unionized_energy_array,SD.length_unionized_energy_array,sizeof(double),double_compare); SD.length_index_grid=SD.length_unionized_energy_array*in.n_isotopes; SD.index_grid=(int*)malloc(SD.length_index_grid*sizeof(int)); assert(SD.index_grid); nb+=SD.length_index_grid*sizeof(int); int *idx_low=(int*)calloc(in.n_isotopes,sizeof(int)); double *energy_high=(double*)malloc(in.n_isotopes*sizeof(double)); assert(idx_low&&energy_high); for(int i=0;i<in.n_isotopes;i++) energy_high[i]=SD.nuclide_grid[i*in.n_gridpoints+1].energy; for(long e=0;e<SD.length_unionized_energy_array;e++){ double ue=SD.unionized_energy_array[e]; for(long i=0;i<in.n_isotopes;i++){ if(ue<energy_high[i]) SD.index_grid[e*in.n_isotopes+i]=idx_low[i]; else if(idx_low[i]==in.n_gridpoints-2) SD.index_grid[e*in.n_isotopes+i]=idx_low[i]; else{ idx_low[i]++; SD.index_grid[e*in.n_isotopes+i]=idx_low[i]; energy_high[i]=SD.nuclide_grid[i*in.n_gridpoints+idx_low[i]+1].energy; } } } free(idx_low); free(energy_high); }
    if(in.grid_type==HASH){ if(mype==0) printf("Intializing hash grid...\n"); SD.length_unionized_energy_array=0; SD.unionized_energy_array=nullptr; SD.length_index_grid=in.hash_bins*in.n_isotopes; SD.index_grid=(int*)malloc(SD.length_index_grid*sizeof(int)); assert(SD.index_grid); nb+=SD.length_index_grid*sizeof(int); double du=1.0/in.hash_bins; for(long e=0;e<in.hash_bins;e++){ double energy=e*du; for(long i=0;i<in.n_isotopes;i++) SD.index_grid[e*in.n_isotopes+i]=grid_search_nuclide(in.n_gridpoints,energy,SD.nuclide_grid+i*in.n_gridpoints,0,in.n_gridpoints-1); } }
    if(mype==0) printf("Intializing material data...\n"); SD.num_nucs=load_num_nucs(in.n_isotopes); SD.length_num_nucs=12; SD.mats=load_mats(SD.num_nucs,in.n_isotopes,&SD.max_num_nucs); SD.length_mats=SD.length_num_nucs*SD.max_num_nucs; SD.concs=load_concs(SD.num_nucs,SD.max_num_nucs); SD.length_concs=SD.length_mats; if(mype==0) printf("Intialization complete. Allocated %.0lf MB of data on CPU.\n",nb/1024.0/1024.0); return SD; }

int *load_num_nucs(long n_isotopes){ int *n=(int*)malloc(12*sizeof(int)); n[0]=(n_isotopes==68)?34:321; n[1]=5; n[2]=4; n[3]=4; n[4]=27; n[5]=21; n[6]=21; n[7]=21; n[8]=21; n[9]=21; n[10]=9; n[11]=9; return n; }
int *load_mats(int *num_nucs,long n_isotopes,int *max_num_nucs){ *max_num_nucs=0; for(int m=0;m<12;m++) if(num_nucs[m]>*max_num_nucs) *max_num_nucs=num_nucs[m]; int *mats=(int*)calloc(12*(*max_num_nucs),sizeof(int)); int mats0_Sml[]={58,59,60,61,40,42,43,44,45,46,1,2,3,7,8,9,10,29,57,47,48,0,62,15,33,34,52,53,54,55,56,18,23,41}; int mats0_Lrg[321]={58,59,60,61,40,42,43,44,45,46,1,2,3,7,8,9,10,29,57,47,48,0,62,15,33,34,52,53,54,55,56,18,23,41}; for(int i=0;i<287;i++) mats0_Lrg[34+i]=68+i; int mats1[]={63,64,65,66,67},mats2[]={24,41,4,5},mats3[]={24,41,4,5},mats4[]={19,20,21,22,35,36,37,38,39,25,27,28,29,30,31,32,26,49,50,51,11,12,13,14,6,16,17},mats5[]={24,41,4,5,19,20,21,22,35,36,37,38,39,25,49,50,51,11,12,13,14},mats6[]={24,41,4,5,19,20,21,22,35,36,37,38,39,25,49,50,51,11,12,13,14},mats7[]={24,41,4,5,19,20,21,22,35,36,37,38,39,25,49,50,51,11,12,13,14},mats8[]={24,41,4,5,19,20,21,22,35,36,37,38,39,25,49,50,51,11,12,13,14},mats9[]={24,41,4,5,19,20,21,22,35,36,37,38,39,25,49,50,51,11,12,13,14},mats10[]={24,41,4,5,63,64,65,66,67},mats11[]={24,41,4,5,63,64,65,66,67}; if(n_isotopes==68) memcpy(mats,mats0_Sml,num_nucs[0]*sizeof(int)); else memcpy(mats,mats0_Lrg,num_nucs[0]*sizeof(int)); memcpy(mats+*max_num_nucs*1,mats1,num_nucs[1]*sizeof(int)); memcpy(mats+*max_num_nucs*2,mats2,num_nucs[2]*sizeof(int)); memcpy(mats+*max_num_nucs*3,mats3,num_nucs[3]*sizeof(int)); memcpy(mats+*max_num_nucs*4,mats4,num_nucs[4]*sizeof(int)); memcpy(mats+*max_num_nucs*5,mats5,num_nucs[5]*sizeof(int)); memcpy(mats+*max_num_nucs*6,mats6,num_nucs[6]*sizeof(int)); memcpy(mats+*max_num_nucs*7,mats7,num_nucs[7]*sizeof(int)); memcpy(mats+*max_num_nucs*8,mats8,num_nucs[8]*sizeof(int)); memcpy(mats+*max_num_nucs*9,mats9,num_nucs[9]*sizeof(int)); memcpy(mats+*max_num_nucs*10,mats10,num_nucs[10]*sizeof(int)); memcpy(mats+*max_num_nucs*11,mats11,num_nucs[11]*sizeof(int)); return mats; }
double *load_concs(int *num_nucs,int max_num_nucs){ uint64_t seed=STARTING_SEED*STARTING_SEED; double *c=(double*)calloc(12*max_num_nucs,sizeof(double)); for(int i=0;i<12;i++) for(int j=0;j<num_nucs[i];j++) c[i*max_num_nucs+j]=LCG_random_double(&seed); return c; }

unsigned long long run_event_based_simulation_baseline(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Running baseline event-based simulation...\n"); launch_baseline_kernel(in,GSD,256); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }
unsigned long long run_event_based_simulation_optimization_1(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Simulation Kernel:\"Optimization 1 - basic sample/lookup kernel splitting\"\n"); allocate_samples(in,GSD,mype); if(mype==0) printf("Beginning optimized simulation...\n"); launch_sampling_kernel(in,GSD,32); launch_lookup1_kernel(in,GSD,32); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }
unsigned long long run_event_based_simulation_optimization_2(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Simulation Kernel:\"Optimization 2 - Material Lookup Kernels\"\n"); allocate_samples(in,GSD,mype); if(mype==0) printf("Beginning optimized simulation...\n"); launch_sampling_kernel(in,GSD,32); for(int m=0;m<12;m++) launch_lookup2_kernel(in,GSD,m,32); get_queue().wait_and_throw(); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }
unsigned long long run_event_based_simulation_optimization_3(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Simulation Kernel:\"Optimization 3 - Fuel or Other Lookup Kernels\"\n"); allocate_samples(in,GSD,mype); if(mype==0) printf("Beginning optimized simulation...\n"); launch_sampling_kernel(in,GSD,32); launch_lookup3_kernel(in,GSD,0,32); launch_lookup3_kernel(in,GSD,1,32); get_queue().wait_and_throw(); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }
unsigned long long run_event_based_simulation_optimization_4(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Simulation Kernel:\"Optimization 4 - All Material Lookup Kernels + Material Sort\"\n"); allocate_samples(in,GSD,mype); if(mype==0) printf("Beginning optimized simulation...\n"); launch_sampling_kernel(in,GSD,32); std::vector<int> mat; std::vector<double> energy; auto counts=copy_samples_to_host_count(GSD,in.lookups,mat,energy); std::vector<int> idx(in.lookups); std::iota(idx.begin(),idx.end(),0); std::sort(idx.begin(),idx.end(),[&](int a,int b){return mat[a]<mat[b];}); std::vector<int> smat(in.lookups); std::vector<double> se(in.lookups); for(int i=0;i<in.lookups;i++){smat[i]=mat[idx[i]]; se[i]=energy[idx[i]];} copy_samples_to_device(smat,se,GSD); int off=0; for(int m=0;m<12;m++){launch_lookup4_kernel(in,GSD,m,counts[m],off,32); off+=counts[m];} get_queue().wait_and_throw(); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }
unsigned long long run_event_based_simulation_optimization_5(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Simulation Kernel:\"Optimization 5 - Fuel/No Fuel Lookup Kernels + Fuel/No Fuel Sort\"\n"); allocate_samples(in,GSD,mype); if(mype==0) printf("Beginning optimized simulation...\n"); launch_sampling_kernel(in,GSD,32); std::vector<int> mat; std::vector<double> energy; auto counts=copy_samples_to_host_count(GSD,in.lookups,mat,energy); int nf=counts[0]; std::vector<int> smat; std::vector<double> se; smat.reserve(in.lookups); se.reserve(in.lookups); for(int i=0;i<in.lookups;i++) if(mat[i]==0){smat.push_back(mat[i]); se.push_back(energy[i]);} for(int i=0;i<in.lookups;i++) if(mat[i]!=0){smat.push_back(mat[i]); se.push_back(energy[i]);} copy_samples_to_device(smat,se,GSD); launch_lookup5_kernel(in,GSD,nf,0,32); launch_lookup5_kernel(in,GSD,in.lookups-nf,nf,32); get_queue().wait_and_throw(); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }
unsigned long long run_event_based_simulation_optimization_6(Inputs in,SimulationData GSD,int mype){ if(mype==0) printf("Simulation Kernel:\"Optimization 6 - Material & Energy Sorts + Material-specific Kernels\"\n"); allocate_samples(in,GSD,mype); if(mype==0) printf("Beginning optimized simulation...\n"); launch_sampling_kernel(in,GSD,32); std::vector<int> mat; std::vector<double> energy; auto counts=copy_samples_to_host_count(GSD,in.lookups,mat,energy); std::vector<int> idx(in.lookups); std::iota(idx.begin(),idx.end(),0); std::sort(idx.begin(),idx.end(),[&](int a,int b){return mat[a]!=mat[b]?mat[a]<mat[b]:energy[a]<energy[b];}); std::vector<int> smat(in.lookups); std::vector<double> se(in.lookups); for(int i=0;i<in.lookups;i++){smat[i]=mat[idx[i]]; se[i]=energy[idx[i]];} copy_samples_to_device(smat,se,GSD); int off=0; for(int m=0;m<12;m++){launch_lookup4_kernel(in,GSD,m,counts[m],off,32); off+=counts[m];} get_queue().wait_and_throw(); if(mype==0) printf("Reducing verification results...\n"); return reduce_verification(GSD,in.lookups); }

int double_compare(const void *a,const void *b){ double A=*(double*)a,B=*(double*)b; return (A>B)-(A<B); }
int NGP_compare(const void *a,const void *b){ NuclideGridPoint A=*(NuclideGridPoint*)a,B=*(NuclideGridPoint*)b; return (A.energy>B.energy)-(A.energy<B.energy); }
double rn_v(void){ static unsigned long seed=1337; unsigned long a=16807,m=2147483647,n1=(a*seed)%m; seed=n1; return (double)n1/m; }
size_t estimate_mem_usage(Inputs in){ size_t ng=in.n_gridpoints*sizeof(NuclideGridPoint), all=in.n_isotopes*ng, ueg=in.n_isotopes*in.n_gridpoints*sizeof(double)+in.n_isotopes*in.n_gridpoints*in.n_isotopes*sizeof(int), hg=in.hash_bins*in.n_isotopes*sizeof(int), mt; if(in.grid_type==UNIONIZED) mt=all+ueg; else if(in.grid_type==NUCLIDE) mt=all; else mt=all+hg; return ceil(mt/(1024.0*1024.0)); }
double get_time(void){ unsigned long us=std::chrono::high_resolution_clock::now().time_since_epoch()/std::chrono::microseconds(1); return (double)us/1.0e6; }
